import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';
const Q=new Function(readFileSync('quote-core.js','utf8')+';return Q')();
const q={id:'Q-123456789abc',issued:'2026-01-01',expires:'2026-01-31',shop:'Fixture',contact:'555-0100',customer:'Customer',vehicle:'',description:'Service',tax:500,items:[{label:'Part',qty:100,cost:4000,rate:5000}]};
assert.equal(Q.total(Q.validate(q,true)),5500);assert.equal(JSON.stringify(Q.publicCopy(q)).includes('"cost"'),false);
for(const change of [{expires:'2025-12-31'},{issued:'2026-02-30'},{paid:{date:'2099-01-01'}},{paid:{date:'invalid'}}])assert.throws(()=>Q.validate({...q,...change},true));
const js=readFileSync('quotes.js','utf8');assert(!js.includes('Approve & send to shop'));assert(!js.includes('Share approval link'));assert(!js.includes("r.hash!==await Q.digest(q)"));assert(js.includes('manual-verified'));console.log('PASS quote validation and disabled approval route: 10 assertions');
assert.equal(Q.publicCopy({...q,trade:'General contractor'}).trade,'General contractor');assert.equal(Q.lines({...q,trade:'General contractor'})[2].startsWith('SERVICE ESTIMATE'),true);

const suppliesQuote={...q,trade:'Mechanic',items:[...q.items,{kind:'supplies',label:'Shop supply charge',qty:100,cost:0,rate:1250}],paid:{date:'2026-01-01'}};assert.equal(Q.total(Q.validate(suppliesQuote,true)),6750);assert.equal(Q.document(suppliesQuote).lines[1].total,1250);const WorkPayments=new Function(readFileSync('payments.js','utf8')+';return WorkPayments')();assert.equal(WorkPayments.rows([suppliesQuote]).find(r=>r.category==='Shop supplies').cents,1250);console.log('PASS quick quote shop supply charge and payment projection');

const sourceQuote={...q,trade:'Mechanic',items:[{...q.items[0],kind:'part',partSource:'purchase'}],partCosts:[{id:'part-fixture',partLine:'0',ledgerId:'fixture-ledger',category:'Parts purchased',cents:4000,date:'2026-01-01',note:'Receipt'}]};
assert.equal(Q.total(Q.validate(sourceQuote,true)),5500);assert(!JSON.stringify(Q.publicCopy(sourceQuote)).includes('partSource'));assert(!JSON.stringify(Q.publicCopy(sourceQuote)).includes('partCosts'));assert.equal(WorkPayments.rows([sourceQuote]).length,0);assert.throws(()=>Q.validate({...sourceQuote,items:[{...sourceQuote.items[0],partSource:'inventory'}]},true));console.log('PASS quick quote source privacy and no estimated expense projection');

const paidSource={...sourceQuote,items:[...sourceQuote.items,{kind:'supplies',label:'Shop supplies',qty:100,cost:0,rate:1250}],paid:{date:'2026-01-01'}};
const original=WorkPayments.rows([paidSource]);assert.equal(original.length,3);const unrelated={id:'unrelated',paid:{date:'2026-01-01'}};const actualExpense={id:'fixture-ledger',job:paidSource.id,cents:4000};const fixed=WorkPayments.correct([paidSource,unrelated],paidSource.id,[actualExpense],{},'2026-01-02T12:00:00.000Z');assert.equal(fixed[0].paid,undefined);assert.equal(fixed[0].paymentCorrections[0].cents,6750);assert.deepEqual(fixed[0].partCosts,paidSource.partCosts);assert.equal(fixed[1],unrelated);assert.equal(WorkPayments.rows([fixed[0]]).length,0);assert.equal(WorkPayments.rows([{...fixed[0],paid:paidSource.paid}]).length,3);assert.equal(Q.validate(fixed[0],true),fixed[0]);assert(!JSON.stringify(Q.publicCopy(fixed[0])).includes('paymentCorrections'));assert.throws(()=>WorkPayments.correct(fixed,paidSource.id));assert.throws(()=>WorkPayments.correct([paidSource],paidSource.id,[],{matches:[{ledgerId:original[0].id}]}));assert.throws(()=>WorkPayments.correct([paidSource],paidSource.id,[{id:'reversal',reversalOf:original[0].id}]));assert.throws(()=>WorkPayments.correct([paidSource],paidSource.id,[original[0]]));assert.equal(paidSource.paid.date,'2026-01-01');console.log('PASS correcting a mistaken quote receipt removes all projected categories, preserves purchases and protects linked receipts');

const removal=new Function(readFileSync('core/job-list.js','utf8')+';return QuoteRemoval')();
assert.equal(removal.mode(q,true),'delete');assert.equal(removal.change([q],q.id,true,[],null,'delete').length,0);assert.equal(removal.mode(fixed[0],true),'archive');const archived=removal.change([fixed[0]],q.id,true,[actualExpense],{},'archive','2026-01-02T12:00:00.000Z')[0];assert.equal(archived.removedAt,'2026-01-02T12:00:00.000Z');assert.deepEqual(archived.partCosts,fixed[0].partCosts);assert.deepEqual(archived.paymentCorrections,fixed[0].paymentCorrections);assert.equal(Q.validate(archived,true),archived);assert(!JSON.stringify(Q.publicCopy(archived)).includes('removedAt'));assert.deepEqual(removal.change([archived],q.id,true,[],{},'restore')[0],fixed[0]);assert.equal(removal.mode(paidSource,true),'archive');assert.equal(WorkPayments.rows(removal.change([paidSource],q.id,true,[],{},'archive')).length,3);assert.throws(()=>removal.change([paidSource],q.id,true,[],{},'delete'));assert.equal(removal.mode({id:'job-1',status:'draft'},false),'delete');assert.equal(removal.mode({id:'job-1',status:'draft',costs:[{}]},false),'archive');console.log('PASS quote deletion, archive, restore and accounting preservation');
